-- An ADMIN or ORGANIZER may suspend a tournament (DRAFT, ACTIVE or IN_PROGRESS) and later resume it.
-- While SUSPENDED nothing about it may change and it is hidden from the public lists; resuming
-- returns it to exactly the status it was suspended from, which is kept in suspended_from_status.

-- V1 declared the status CHECK inline, so its name was generated by PostgreSQL
-- (tournaments_status_check); it is looked up by definition rather than trusted by name.
DO $$
DECLARE
    constraint_name TEXT;
BEGIN
    FOR constraint_name IN
        SELECT c.conname FROM pg_constraint c
        WHERE c.conrelid = 'tournaments'::regclass
          AND c.contype = 'c'
          AND pg_get_constraintdef(c.oid) LIKE '%status%'
          AND pg_get_constraintdef(c.oid) LIKE '%IN_PROGRESS%'
    LOOP
        EXECUTE format('ALTER TABLE tournaments DROP CONSTRAINT %I', constraint_name);
    END LOOP;
END $$;

ALTER TABLE tournaments
    ADD CONSTRAINT tournaments_status_check
        CHECK (status IN ('DRAFT', 'ACTIVE', 'IN_PROGRESS', 'FINISHED', 'SUSPENDED'));

ALTER TABLE tournaments
    ADD COLUMN suspended_from_status VARCHAR(15) NULL
        CHECK (suspended_from_status IS NULL OR suspended_from_status IN ('DRAFT', 'ACTIVE', 'IN_PROGRESS'));

-- The origin is recorded exactly while the tournament is suspended.
ALTER TABLE tournaments
    ADD CONSTRAINT ck_tournaments_suspended_from
        CHECK ((status = 'SUSPENDED') = (suspended_from_status IS NOT NULL));
